    {
        WarehouseState.OnWarehouseChanged += OnStateChanged;
        AlertService.OnAlertDataChanged += OnStateChanged;
        AlertService.StartPolling();
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

