    {
        var match = WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == id);
        return match == default ? id : match.Name;
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= OnStateChanged;
        AlertService.OnAlertDataChanged -= OnStateChanged;
        AlertService.StopPolling();
    }
}

