@page "/dashboard"
@using sv_0c26778ed74945698509b592ec832f67.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">
            @GetWarehouseName(WarehouseState.CurrentWarehouseId)
            <span class="text-muted fs-6">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            @if (AlertService.LatestLowStockCount > 0)
            {
                <span class="text-danger fs-3 fw-bold">@AlertService.LatestLowStockCount</span>
                <span class="text-muted ms-2">items below minimum stock level</span>
            }
            else
            {
                <span class="text-success fs-3 fw-bold">All Clear</span>
                <span class="text-muted ms-2">— no items below minimum level</span>
            }
        </p>
        <small class="text-muted">Refreshes every 10 seconds</small>
    </div>
</div>

<div class="card">
    <div class="card-body">
        <h5 class="card-title">Polling Status</h5>
        <p class="card-text text-success">● Active — monitoring @GetWarehouseName(WarehouseState.CurrentWarehouseId)</p>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += OnStateChanged;
        AlertService.OnAlertDataChanged += OnStateChanged;
        AlertService.StartPolling();
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private static string GetWarehouseName(string id)
    {
        var match = WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == id);
        return match == default ? id : match.Name;
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= OnStateChanged;
        AlertService.OnAlertDataChanged -= OnStateChanged;
        AlertService.StopPolling();
    }
}

